const PAT = 'REDACTED__SET_AS_N8N_ENV_VAR_AIRTABLE_PAT';
const BASE_ID = 'appmBaUD39bNFM4QA';
const TABLE_ID = 'tblQkG1DeczNyWsyM';

const body = $input.first().json.body || $input.first().json;
const toolCallList = body?.message?.toolCallList || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') args = JSON.parse(args);

const callId = body?.message?.call?.id || '';
const callerPhone = body?.message?.call?.customer?.number || '';

const customerName = args.customerName || 'Unknown';
const orderSummary = args.orderSummary || '';
const location = args.location || '';
const language = args.language || 'en';
const estimatedTotal = typeof args.estimatedTotal === 'number' ? args.estimatedTotal : parseFloat(args.estimatedTotal) || 0;
const items = args.items || [];

// Build human-readable items list
const itemsText = items.map(i => {
  let line = (i.quantity || 1) + 'x ' + i.name;
  if (i.modifiers && i.modifiers.length) line += ' (' + i.modifiers.join(', ') + ')';
  if (i.price) line += ' — $' + Number(i.price).toFixed(2);
  return line;
}).join('\n');

// Write to Airtable
const record = {
  fields: {
    'fld0ueP1iMC8t8w3H': customerName,
    'fld5t3J3iVgrZMWqN': itemsText || orderSummary,
    'fldzT5EEtMrmx2Smp': location,
    'fldHWx4jyAI8ih68i': callerPhone,
    'fldZpM4vLB5ryl2Eg': estimatedTotal,
    'fld5UKntch8ztKHyE': language,
    'fldBpeYTgz9dBVbwH': callId,
    'fldtavp7YkLSt1OZr': new Date().toISOString(),
    'flditfDYa3x08ZaWR': JSON.stringify(args, null, 2)
  }
};

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.airtable.com/v0/' + BASE_ID + '/' + TABLE_ID,
  headers: { Authorization: 'Bearer ' + PAT, 'Content-Type': 'application/json' },
  body: JSON.stringify({ records: [record] })
});

return [{
  json: {
    results: [{
      toolCallId,
      result: 'Order received for ' + customerName + '. Ready in about 15 to 20 minutes.'
    }]
  }
}];
